// priority: 1007
// kubejs/startup_scripts/autogeneratedyabbadabbadoo/framework/block_types.js
global.BLOCK_TIERS = {
  iron: [
    'osmium',
    'iridium',
    'palladium',
    'platinum',
    'enderium',
    'signalum',
    'lumium',
    'uranium',
    'titanium',
    'ferroboron'
  ],

  diamond: [
    'extreme',
    'tough_alloy',
    'hard_carbon',
    'thermoconducting',
    'draconium',
    'awakened_draconium'
  ],

  netherite: [
    'neutronium'
  ]
}

var getBlockTier = function(id) {
  if (global.BLOCK_TIERS.netherite.includes(id)) {
    return {
      tag: 'neoforge:needs_netherite_tool',
      multiplier: 20
    }
  }

  if (global.BLOCK_TIERS.diamond.includes(id)) {
    return {
      tag: 'minecraft:needs_diamond_tool',
      multiplier: 3
    }
  }

  if (global.BLOCK_TIERS.iron.includes(id)) {
    return {
      tag: 'minecraft:needs_iron_tool',
      multiplier: 1.5
    }
  }

  return {
    tag: 'minecraft:needs_stone_tool',
    multiplier: 1
  }
}


StartupEvents.registry('block', event => {
  for (var mat of global.MATERIALS) {
    if (!mat.flags.includes('Block')) continue

    var setPath = 'mkwrc:block/sets/' + mat.set
    var tier = getBlockTier(mat.id)

    event.create(mat.id + '_block')
      .displayName(mat.display + ' Block')
      //.displayName(mat.chromatic + mat.display + ' Block')
      .texture('up', setPath + '/block')
      .texture('down', setPath + '/block')
      .texture('north', setPath + '/block')
      .texture('south', setPath + '/block')
      .texture('east', setPath + '/block')
      .texture('west', setPath + '/block')
      .color(0, mat.color)
      .hardness(5.0 * tier.multiplier)
      .resistance(6.0 * tier.multiplier)
      .tagBlock('minecraft:mineable/pickaxe')
      .tagBlock(tier.tag)
      .tagItem('c:storage_blocks')
      .tagItem('c:storage_blocks/' + mat.id)
      .item(item => {
        item.color(0, mat.color)
      })
  }
})